#!/usr/bin/env python3
"""Small random Horn ontologies with inverses, at-most restrictions and nested existential
restrictions, for item 710's search for few axioms with many conclusions.
Usage: gen.py DIR COUNT SEED"""
import random, sys
d, count, seed = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
def role(r):
    k = r.randrange(3)
    return f"ObjectInverseOf(:r{k})" if r.randrange(4) == 0 else f":r{k}"
def cls(r, depth=0):
    t = r.randrange(6 if depth < 2 else 2)
    a = f":A{r.randrange(8)}"
    if t <= 1: return a
    if t == 2: return f"ObjectIntersectionOf({a} :A{r.randrange(8)})"
    return f"ObjectSomeValuesFrom({role(r)} {cls(r, depth+1)})"
for n in range(count):
    r = random.Random(f"{seed}:{n}")
    s = []
    for _ in range(8 + r.randrange(8)):
        k = r.randrange(8)
        A = f":A{r.randrange(8)}"
        if k == 0: s.append(f"SubClassOf({A} :A{r.randrange(8)})")
        elif k == 1: s.append(f"SubClassOf({A} ObjectSomeValuesFrom({role(r)} {cls(r,1)}))")
        elif k == 2: s.append(f"SubClassOf(ObjectSomeValuesFrom({role(r)} {cls(r,1)}) {A})")
        elif k == 3: s.append(f"SubClassOf({A} ObjectAllValuesFrom({role(r)} :A{r.randrange(8)}))")
        elif k == 4: s.append(f"SubClassOf({A} ObjectMaxCardinality(1 {role(r)} :A{r.randrange(8)}))")
        elif k == 5: s.append(f"EquivalentClasses({A} ObjectSomeValuesFrom({role(r)} {cls(r,1)}))")
        elif k == 6: s.append(f"SubClassOf(ObjectIntersectionOf({A} :A{r.randrange(8)}) :A{r.randrange(8)})")
        else: s.append(f"SubClassOf({A} {cls(r)})")
    for _ in range(1 + r.randrange(3)):
        p, q = r.randrange(3), r.randrange(3)
        k = r.randrange(5)
        if k == 0: s.append(f"SubObjectPropertyOf(:r{p} {role(r)})")
        elif k == 1 and p != q: s.append(f"InverseObjectProperties(:r{p} :r{q})")
        elif k == 2: s.append(f"FunctionalObjectProperty(:r{p})")
        elif k == 3: s.append(f"InverseFunctionalObjectProperty(:r{p})")
        else: s.append(f"InverseObjectProperties(:r{p} :r{(p+1)%3})")
    body = "\n".join(s)
    with open(f"{d}/g{n:05}.ofn", "w") as f:
        f.write("Prefix(:=<http://e/>)\nOntology(<http://e/o>\n" + body + "\n)\n")
